// Squeezer — Adw.Squeezer
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles squeezer with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { FoldThresholdPolicy, SqueezerTransitionType } from "@/lib/enums"

export interface SqueezerProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.Squeezer */
  allowNone?: boolean

  /** gboolean, from Adw.Squeezer */
  homogeneous?: boolean

  /** gboolean, from Adw.Squeezer */
  interpolateSize?: boolean

  /** FoldThresholdPolicy, from Adw.Squeezer */
  switchThresholdPolicy?: FoldThresholdPolicy

  /** guint, from Adw.Squeezer */
  transitionDuration?: number

  /** SqueezerTransitionType, from Adw.Squeezer */
  transitionType?: SqueezerTransitionType

  /** gfloat, from Adw.Squeezer */
  xalign?: number

  /** gfloat, from Adw.Squeezer */
  yalign?: number
}

export function Squeezer({ className, children }: SqueezerProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
